    function transliterate($text) {
        $replace = array(
            'А'=>'a','Б'=>'b','В'=>'v','Г'=>'g','Д'=>'d',
            'Е'=>'e','Ё'=>'e','Ж'=>'zh','З'=>'z','И'=>'i',
            'Й'=>'y','К'=>'k','Л'=>'l','М'=>'m','Н'=>'n',
            'О'=>'o','П'=>'p','Р'=>'r','С'=>'s','Т'=>'t',
            'У'=>'U','Ф'=>'F','Х'=>'Kh','Ц'=>'Ts','Ч'=>'Ch',
            'Ш'=>'sh','Щ'=>'sch','Ы'=>'y','Э'=>'e','Ю'=>'yu','Я'=>'ya',
            'а'=>'a','б'=>'b','в'=>'v','г'=>'g','д'=>'d',
            'е'=>'e','ё'=>'e','ж'=>'zh','з'=>'z','и'=>'i',
            'й'=>'y','к'=>'k','л'=>'l','м'=>'m','н'=>'n',
            'о'=>'o','п'=>'p','р'=>'r','с'=>'s','т'=>'t',
            'у'=>'u','ф'=>'f','х'=>'kh','ц'=>'ts','ч'=>'ch',
            'ш'=>'sh','щ'=>'sch','ы'=>'y','э'=>'e','ю'=>'yu','я'=>'ya', ' ' => '_'
        );
        return strtr($text, $replace);
    }


